const owner = "danielm5", repo = "tiffcraft";
const issue = await tools.github.issue_read({ issue_number: 38, method: "get", owner, repo });
return issue.body;

const owner = "danielm5", repo = "tiffcraft";
const issue = await tools.github.issue_read({ issue_number: 38, method: "get", owner, repo });
return issue.body;

const owner = "danielm5", repo = "tiffcraft";

const current = await tools.github.issue_read({ issue_number: 38, method: "get", owner, repo });

const updatedBody = current.body.replace(
  "Small images (64×48 base, or 61×47/63×61/62×47 for odd cases). Generated independently (magick preferred, Pillow acceptable). 18 images:",
  "Small images (64×48 base, or 61×47/63×61/62×47 for odd cases). Generated with ImageMagick (magick) command line. 18 images:"
).replace(
  "`ycbcr-*.ppm` for each test image, generated independently. Ground-truth RGB pixel values for validating TiffCraft's YCbCr→RGB conversion.",
  "`ycbcr-*.ppm` for each test image, generated with ImageMagick (magick) command line. Ground-truth RGB pixel values for validating TiffCraft's YCbCr→RGB conversion."
);

const updated = await tools.github.issue_write({
  method: "update",
  owner,
  repo,
  issue_number: 38,
  title: current.title,
  body: updatedBody,
});

return updated;

